CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, telegram_id BIGINT NOT NULL UNIQUE, username VARCHAR(255), first_name VARCHAR(255), last_name VARCHAR(255), created_at TIMESTAMPTZ NOT NULL, last_login_at TIMESTAMPTZ NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS watchlist_items (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, gift_id BIGINT NOT NULL REFERENCES gifts(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL, CONSTRAINT uq_watchlist_user_gift UNIQUE(user_id, gift_id));
CREATE TABLE IF NOT EXISTS portfolio_wallets (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, address VARCHAR(128) NOT NULL, label VARCHAR(255), created_at TIMESTAMPTZ NOT NULL, CONSTRAINT uq_portfolio_user_address UNIQUE(user_id, address));
CREATE TABLE IF NOT EXISTS alert_rules (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, gift_id BIGINT REFERENCES gifts(id) ON DELETE CASCADE, rule_type VARCHAR(32) NOT NULL, threshold NUMERIC(24,9) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS alert_events (id BIGSERIAL PRIMARY KEY, rule_id BIGINT NOT NULL REFERENCES alert_rules(id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, gift_id BIGINT REFERENCES gifts(id) ON DELETE CASCADE, message TEXT NOT NULL, observed_value NUMERIC(24,9), is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS ix_alert_events_user_created ON alert_events(user_id, created_at);
